<template><view class="page"><nav-bar title="我的试卷" :showBack="true" placeholder/><view class="toolbar"><view class="search"><input v-model="keyword" placeholder="搜索试卷" confirm-type="search" @confirm="load"/></view><view class="tabs"><text :class="!status?'active':''" @click="status='';load()">全部</text><text :class="status==='draft'?'active':''" @click="status='draft';load()">草稿</text><text :class="status==='completed'?'active':''" @click="status='completed';load()">已完成</text></view></view><scroll-view scroll-y class="list"><view v-for="p in papers" :key="p.id" class="card"><view @click="open(p)"><view class="top"><text class="name">{{p.name}}</text><text :class="['status',p.status]">{{p.status==='draft'?'草稿':'已完成'}}</text></view><text class="meta">{{p.subject}} · {{p.category}} · {{p.questionCount}}题 · {{p.totalScore}}分</text><text class="time">更新于 {{p.updateTime}}</text></view><view class="actions"><text @click="open(p)">{{p.status==='draft'?'继续编辑':'预览'}}</text><text @click="copy(p)">复制</text><text class="danger" @click="remove(p)">删除</text></view></view><view v-if="!loading&&!papers.length" class="empty">没有符合条件的试卷</view></scroll-view></view></template>
<script>import NavBar from '@/components/nav-bar/nav-bar.vue';import{listPapers,copyPaper,deletePaper}from'@/api/paper.js';export default{components:{NavBar},data(){return{papers:[],status:'',keyword:'',loading:false}},onShow(){this.load()},methods:{async load(){this.loading=true;try{const r=await listPapers({status:this.status,keyword:this.keyword});this.papers=r.data||[]}finally{this.loading=false}},open(p){uni.navigateTo({url:p.status==='draft'?`/subpackage_ai/paperSelect/paperSelect?paperId=${p.id}`:`/subpackage_ai/paperPreview/paperPreview?paperId=${p.id}`})},async copy(p){const r=await copyPaper(p.id);uni.showToast({title:'已复制为草稿',icon:'success'});this.open(r.data)},remove(p){uni.showModal({title:'删除试卷',content:`确认删除“${p.name}”？`,success:async r=>{if(r.confirm){await deletePaper(p.id);this.load()}}})}}}</script>
<style scoped lang="scss">.page{min-height:100vh;background:#f5f8fc}.toolbar{padding:18rpx 24rpx;background:#fff}.search{background:#f2f5fa;border-radius:30rpx;padding:14rpx 20rpx}.search input{font-size:25rpx}.tabs{display:flex;margin-top:18rpx}.tabs text{margin-right:36rpx;color:#818da0;padding-bottom:10rpx}.tabs .active{color:#4d78e8;border-bottom:4rpx solid #4d78e8}.list{height:calc(100vh - 260rpx);padding:20rpx 24rpx;box-sizing:border-box}.card{background:#fff;border-radius:18rpx;padding:24rpx;margin-bottom:15rpx}.top{display:flex;justify-content:space-between}.name{font-size:29rpx;font-weight:600;color:#27364d}.status{font-size:21rpx;border-radius:16rpx;padding:6rpx 12rpx}.draft{background:#fff4d9;color:#c48920}.completed{background:#e7f7ed;color:#31905a}.meta,.time{display:block;color:#8f9bad;font-size:23rpx;margin-top:12rpx}.actions{border-top:1rpx solid #edf0f5;margin-top:18rpx;padding-top:16rpx;text-align:right}.actions text{color:#4d78e8;font-size:23rpx;margin-left:28rpx}.actions .danger{color:#df6565}.empty{text-align:center;color:#a0aabb;padding:120rpx}</style>
